from pathlib import Path

# Security patch script; intentionally idempotent only when run once on the original code.
def rep(s, old, new, label):
    if old not in s: raise SystemExit(label)
    return s.replace(old, new, 1)

p=Path('server/db.ts'); s=p.read_text()
s=rep(s,'export async function listWorkOrders(filters: { status?: string; priority?: string; category?: string; location?: string; from?: Date; to?: Date; search?: string }) {','export async function listWorkOrders(filters: { status?: string; priority?: string; category?: string; location?: string; from?: Date; to?: Date; search?: string; requesterUserId?: string; assignedTechId?: string }) {','db signature')
s=rep(s,'  if (filters.search) conditions.push(or(like(workOrders.woId, `%${filters.search}%`), like(workOrders.description, `%${filters.search}%`)));\n  return db.select().from(workOrders).where(conditions.length ? and(...conditions) : undefined).orderBy(desc(workOrders.createdAt));','  if (filters.search) conditions.push(or(like(workOrders.woId, `%${filters.search}%`), like(workOrders.description, `%${filters.search}%`)));\n  if (filters.requesterUserId) conditions.push(eq(workOrders.requesterUserId, filters.requesterUserId));\n  if (filters.assignedTechId) conditions.push(eq(workOrders.assignedTechId, filters.assignedTechId));\n  return db.select().from(workOrders).where(conditions.length ? and(...conditions) : undefined).orderBy(desc(workOrders.createdAt));','db filters')
s=rep(s,'export async function markNotificationRead(notificationId: string) {\n  const db = await getDb();\n  if (!db) throw new Error("Database unavailable");\n  await db.update(notifications).set({ isRead: true }).where(eq(notifications.notificationId, notificationId));\n  return { success: true } as const;\n}','export async function markNotificationRead(notificationId: string, recipientUserId: string) {\n  const db = await getDb();\n  if (!db) throw new Error("Database unavailable");\n  await db.update(notifications).set({ isRead: true }).where(and(eq(notifications.notificationId, notificationId), eq(notifications.recipientUserId, recipientUserId)));\n  return { success: true } as const;\n}','db notifications')
p.write_text(s)

p=Path('server/routers.ts'); s=p.read_text()
anchor='export function canSetTechnicianAvailability(user: { openId?: string; role?: string } | null, techId: string) {\n  return Boolean(user && (hasRole(user, ["ADMIN", "SUPERVISOR"]) || (user.role === "TECHNICIAN" && user.openId === techId)));\n}\n'
addition=anchor+'\nasync function assertWorkOrderAccess(user: { openId: string; role?: string }, woId: string) {\n  const detail = await getWorkOrder(woId);\n  if (!detail) throw new Error("WORK_ORDER_NOT_FOUND");\n  const order = detail.workOrder;\n  if (hasRole(user, ["ADMIN", "SUPERVISOR"])) return detail;\n  if (user.role === "REPORTER" && order.requesterUserId === user.openId) return detail;\n  if (user.role === "TECHNICIAN" && order.assignedTechId === user.openId) return detail;\n  throw new Error("FORBIDDEN");\n}\n\nconst allowedTransitions: Record<string, string[]> = { OPEN: ["ASSIGNED", "IN_PROGRESS", "PENDING_PARTS"], ASSIGNED: ["IN_PROGRESS", "PENDING_PARTS"], IN_PROGRESS: ["PENDING_PARTS", "COMPLETED"], PENDING_PARTS: ["IN_PROGRESS"], COMPLETED: ["CLOSED"], CLOSED: [] };\n'
s=rep(s,anchor,addition,'router helper')
s=s.replace('dashboard: router({ stats: publicProcedure.query(() => getDashboardStats()) }),','dashboard: router({ stats: protectedProcedure.query(() => getDashboardStats()) }),')
s=s.replace('list: publicProcedure.input(z.object({ status: z.string().optional(), priority: z.string().optional(), category: z.string().optional(), location: z.string().optional(), from: dateInput, to: dateInput, search: z.string().optional() }).optional()).query(({ input }) => listWorkOrders(input ?? {})),\n    detail: publicProcedure.input(z.object({ woId: z.string().min(1) })).query(({ input }) => getWorkOrder(input.woId)),','list: protectedProcedure.input(z.object({ status: z.string().optional(), priority: z.string().optional(), category: z.string().optional(), location: z.string().optional(), from: dateInput, to: dateInput, search: z.string().optional() }).optional()).query(({ input, ctx }) => { const filters={...(input??{})}; if(ctx.user.role==="REPORTER") return listWorkOrders({...filters,requesterUserId:ctx.user.openId}); if(ctx.user.role==="TECHNICIAN") return listWorkOrders({...filters,assignedTechId:ctx.user.openId}); return listWorkOrders(filters); }),\n    detail: protectedProcedure.input(z.object({ woId: z.string().min(1) })).query(({ input, ctx }) => assertWorkOrderAccess(ctx.user, input.woId)),')
s=s.replace('if (!canEdit(ctx.user)) throw new Error("FORBIDDEN");\n      if (input.values.categoryCode !== undefined && !canSetWorkOrderCategory(ctx.user))','if (!canEdit(ctx.user)) throw new Error("FORBIDDEN");\n      await assertWorkOrderAccess(ctx.user, input.woId);\n      if (input.values.categoryCode !== undefined && !canSetWorkOrderCategory(ctx.user))',1)
s=s.replace('if (!canChangeStatus(ctx.user, input.toStatus)) throw new Error("FORBIDDEN");\n      if (requiresAfterPhoto(input.toStatus)','if (!canChangeStatus(ctx.user, input.toStatus)) throw new Error("FORBIDDEN");\n      const detail=await assertWorkOrderAccess(ctx.user,input.woId);\n      const currentStatus=detail.workOrder.statusCode;\n      if(!allowedTransitions[currentStatus]?.includes(input.toStatus)) throw new Error(`INVALID_STATUS_TRANSITION:${currentStatus}->${input.toStatus}`);\n      if (requiresAfterPhoto(input.toStatus)',1)
s=s.replace('fromStatus: input.fromStatus ?? null','fromStatus: currentStatus',1)
s=s.replace('logId: `LOG-${Date.now()}`','logId: `LOG-${Date.now()}-${Math.random().toString(36).slice(2,8)}`',1)
s=s.replace('if (!canChangeStatus(ctx.user, "PENDING_PARTS")) throw new Error("FORBIDDEN");\n      return setWorkOrderPendingParts','if (!canChangeStatus(ctx.user, "PENDING_PARTS")) throw new Error("FORBIDDEN");\n      await assertWorkOrderAccess(ctx.user,input.woId);\n      return setWorkOrderPendingParts',1)
s=s.replace('if (!canEdit(ctx.user)) throw new Error("FORBIDDEN");\n      if (input.attachmentType !== "OTHER"','if (!canEdit(ctx.user)) throw new Error("FORBIDDEN");\n      await assertWorkOrderAccess(ctx.user,input.woId);\n      if (input.attachmentType !== "OTHER"',1)
s=s.replace('parts: router({\n    list: publicProcedure','parts: router({\n    list: protectedProcedure',1)
s=s.replace('partIssues: router({\n    list: publicProcedure','partIssues: router({\n    list: protectedProcedure',1)
s=s.replace('list: protectedProcedure.input(z.object({ userId: z.string().optional() }).optional()).query(({ input, ctx }) => listNotifications(input?.userId ?? ctx.user?.openId)),','list: protectedProcedure.query(({ ctx }) => listNotifications(ctx.user.openId)),')
s=s.replace('markRead: protectedProcedure.input(z.object({ notificationId: z.string().min(1) })).mutation(({ input }) => markNotificationRead(input.notificationId)),','markRead: protectedProcedure.input(z.object({ notificationId: z.string().min(1) })).mutation(({ input, ctx }) => markNotificationRead(input.notificationId, ctx.user.openId)),')
p.write_text(s)
print('Security patch applied')
